const schema = {
  name: "cancel_order",
  required: ["order_id", "reason"],
  props: {
    order_id: { type: "string", pattern: "^ord_[a-z0-9]{4}$" },
    reason:   { type: "string", enum: ["customer_request", "fraud", "duplicate"] },
    notify:   { type: "boolean" }
  }
};

function validate(name, args) {
  if (name !== schema.name) return "reject: unknown tool " + name;
  const errs = [];
  for (const k of Object.keys(args)) if (!(k in schema.props)) errs.push("unexpected field " + k);
  for (const r of schema.required) if (!(r in args)) errs.push("missing required " + r);
  for (const [k, spec] of Object.entries(schema.props)) {
    if (!(k in args)) continue;
    const v = args[k], t = typeof v;
    if (spec.type === "string" && t !== "string") { errs.push(k + " wrong type: want string got " + t); continue; }
    if (spec.type === "boolean" && t !== "boolean") { errs.push(k + " wrong type: want boolean got " + t); continue; }
    if (spec.enum && !spec.enum.includes(v)) errs.push(k + " not in enum");
    if (spec.pattern && !new RegExp(spec.pattern).test(v)) errs.push(k + " fails pattern");
  }
  return errs.length === 0 ? "valid" : "reject: " + errs.join("; ");
}

const calls = [
  ["cancel_order", { order_id: "ord_9f3c", reason: "customer_request" }],
  ["cancel_order", { order_id: "9f3c", reason: "angry_customer", notify: "yes" }],
  ["cancel_order", { reason: "fraud" }]
];

console.log(calls.map(([n, a]) => validate(n, a)).join("\n"));

const TOOL_TOKENS = 500, NUM_TOOLS = 10, MAX_STEPS = 8;
const emitted = [
  ["lookup_order", "id=ord_1"],
  ["lookup_order", "id=ord_1"],
  ["lookup_order", "id=ord_1"],
  ["refund", "id=ord_1"]
];
let steps = 0, stoppedBy = "end_turn", prev = null;
for (let i = 0; i < emitted.length; i++) {
  if (i >= MAX_STEPS) { stoppedBy = "max_steps"; break; }
  const cur = emitted[i][0] + "|" + emitted[i][1];
  if (cur === prev) { stoppedBy = "repeat_guard"; break; }
  prev = cur;
  steps++;
}
const modelCalls = steps + 1;
const schemaTax = NUM_TOOLS * TOOL_TOKENS * modelCalls;
console.log(`steps=${steps} modelCalls=${modelCalls} stoppedBy=${stoppedBy} schemaTax=${schemaTax}`);
